SELECT p.post_id, p.title, p.team, p.sport, p.price, p.grade AS `condition`, p.size,
       p.delivery_type AS tradeType, p.status, p.view_count, p.wish_count AS likeCount, p.created_at,
       m.member_id AS sellerMemberId, m.nickname AS sellerNickname,
       m.profile_image_url AS sellerProfileImageUrl,
       m.manner_score AS sellerMannerScore,
       (SELECT pi.image_url FROM post_image pi WHERE pi.post_id = p.post_id
                            ORDER BY pi.sort_order ASC LIMIT 1) AS thumbnailUrl,
       CASE WHEN w.member_id IS NOT NULL THEN true ELSE false END AS isLiked
FROM post p JOIN member m ON p.seller_id = m.member_id
            LEFT JOIN wish w ON w.post_id = p.post_id AND w.member_id = #{memberId}
WHERE p.status = 'ON_SALE'
